text:
flowchart TD
    A(["Début : appel à calcRefs"]) --&gt; B{"dataCsv et dataItemSet existent-ils ?"}
    B -- Oui --&gt; C@{ label: "Afficher 'Calcul des références' dans la console, mettre à jour le bouton d'export, afficher le loader" }
    B -- Non --&gt; U(["Fin du programme"])
    C --&gt; D["Récupérer les en-têtes du CSV et la propriété o:title"]
    D --&gt; E["Itérer sur chaque ligne du CSV"]
    E --&gt; F["Itérer sur chaque en-tête"]
    F --&gt; G@{ label: "L'en-tête correspond-il à un ItemSet ?" }
    G -- Oui --&gt; H@{ label: "Trouver l'ItemSet correspondant" }
    H --&gt; I@{ label: "Récupérer l'ItemSet & séparer les valeurs avec le séparateur" }
    I --&gt; J@{ label: "Pour chaque valeur, trouver l'item dans l'ItemSet par titre" }
    J --&gt; K{"Item trouvé ?"}
    K -- Oui --&gt; L@{ label: "Ajouter l'ID de l'item à la liste des valeurs" }
    K -- Non --&gt; M["Ajouter la valeur brute à la liste des valeurs"]
    L --&gt; N["Concaténer les valeurs avec le séparateur"]
    M --&gt; N
    N --&gt; P["Construire la nouvelle ligne"]
    G -- Non --&gt; O@{ label: "Garder la valeur d'origine pour cette colonne" }
    O --&gt; P
    P --&gt; Q["Ajouter la nouvelle ligne à nData"]
    Q --&gt; R["Toutes les lignes sont-elles traitées ?"]
    R -- Non --&gt; F
    R -- Oui --&gt; S["Mettre à jour dataResult et afficher le tableau"]
    S --&gt; T["Cacher le loader"]
    T --&gt; U

    C@{ shape: rect }
    G@{ shape: diamond }
    H@{ shape: rect }
    I@{ shape: rect }
    J@{ shape: rect }
    L@{ shape: rect }
    O@{ shape: rect }

classDiagram
direction TB
    class calcRefs {
        +dataCsv: Array
        +dataItemSet: Array
        +dataResult: Array
        +separateur: String
        +propTitle: Number
        +calcRefs()
    }

    class ItemSet {
        +dcterms:title: String
        +id: Number
        +data: Array
    }

    class Item {
        +dcterms:title: String
        +o:id: Number
    }

    class Loader {
        +show() void
        +hide(force: Boolean) void
    }

    class a.omk {
        +loader: Loader
        +getPropByTerm(term: String) Object
        +searchItems(query: String) Array
    }

    calcRefs --&gt; ItemSet
    calcRefs --&gt; a.omk
    ItemSet --&gt; Item
    a.omk --&gt; Loader
